    ok = ok && GetBumpTexture(1, 0, 0, pre, false) == &g_frameTex && g_frame.seenFlags == 0 && !pre;
    ok = ok && GetBumpTexture(1, 0, 0, pre, true) == &g_frameTex && g_frame.seenFlags == 0x11;
